    public virtual void handleTrades(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "ch": "trades::1",
        //         "ts": 1788546815589,
        //         "ets": 1788546815543,
        //         "sq": 35879871600,
        //         "data": {
        //             "tid": 3738280849593744,
        //             "iid": 1,
        //             "side": "long",
        //             "p": "7714",
        //             "qty": "0.00136",
        //             "ts": 1788546565789,
        //             "hash": "0x"
        //         }
        //     }
        //
        // the asyncapi spec describes the data field as an array of trade objects while typing it
        // as a single object, so both shapes are handled here
        //
        object data = this.safeValue(message, "data");
        object rows = new List<object>() {};
        if (((data is IList<object>) || (data.GetType().IsGenericType && data.GetType().GetGenericTypeDefinition().IsAssignableFrom(typeof(List<>)))))
        {
            rows = data;
        } else
        {
            ((IList<object>)rows).Add(data);
        }
        int rowsLength = getArrayLength(rows);
        if ((rowsLength == 0))
        {
            return;
        }
        IDictionary<string, object> first = this.safeDict(rows, 0, new Dictionary<string, object>() {});
        string? marketId = this.safeString(first, "iid");
        Dictionary<string, object> market = this.safeMarket(marketId);
        string? symbol = this.safeString(market, "symbol", "");
        if (!(((symbol != null) && ((IDictionary<string, object>)this.trades).ContainsKey(symbol))))
        {
            Int64? limit = this.safeInteger(this.options, "tradesLimit", 1000);
            var stored = new ArrayCache(limit);
            this.trades[(string)symbol] = stored;
        }
        ccxt.pro.ArrayCache trades = ((ccxt.pro.ArrayCache)(this.trades != null && symbol != null && this.trades.ContainsKey(symbol) ? this.trades[symbol] : null));
        for (int i = 0; i < rowsLength; i++)
        {
            IDictionary<string, object> row = this.safeDict(rows, i, new Dictionary<string, object>() {});
            ccxt.Trade trade = this.parseWsTrade(row, market);
            trades.append(ccxt.BaseExchange.FromTrade(trade));
        }
        string messageHash = ("trade:" + symbol);
        client.resolve(trades, messageHash);
    }

    public override ccxt.Trade parseWsTrade(object trade, object market = null)
    {
        //
        //     {
        //         "tid": 3738280849593744,
        //         "iid": 1,
        //         "side": "long",
        //         "p": "7714",
        //         "qty": "0.00136",
        //         "ts": 1788546565789,
        //         "hash": "0x"
        //     }
        //
        string? marketId = this.safeString(trade, "iid");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger(trade, "ts");
        string? side = this.safeStringLower(trade, "side");
