    public virtual void handleOHLCV(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "ch": "klines::1::1h",
        //         "ts": 1788547135685,
        //         "ets": 1788547135685,
        //         "sq": 35880657084,
        //         "data": [
        //             [ 1788537600000, "7724.9", "7724.9", "7724.2", "7724.2", "0.02872", 5 ]
        //         ]
        //     }
        //
        // only the candles touched by fresh trades are included, the array can be empty
        //
        string? ch = this.safeString(message, "ch", "");
        List<object> parts = ch.Split(new [] {"::"}, StringSplitOptions.None).ToList<object>();
        string? marketId = this.safeString(parts, 1);
        string? interval = this.safeString(parts, 2);
        Dictionary<string, object> market = this.safeMarket(marketId);
        string? symbol = this.safeString(market, "symbol", "");
        string? timeframe = this.findTimeframe(interval);
        if ((timeframe == null))
        {
            return;
        }
        List<object> rows = this.safeList(message, "data", new List<object>() {});
        int rowsLength = rows.Count;
        if ((rowsLength == 0))
        {
            return;
        }
        if (!(((symbol != null) && ((IDictionary<string, object>)this.ohlcvs).ContainsKey(symbol))))
        {
            this.ohlcvs[(string)symbol] = new Dictionary<string, object>() {};
        }
        if (!(inOp((this.ohlcvs != null && symbol != null && this.ohlcvs.ContainsKey(symbol) ? this.ohlcvs[symbol] : null), timeframe)))
        {
            Int64? limit = this.safeInteger(this.options, "OHLCVLimit", 1000);
            var stored = new ArrayCacheByTimestamp(limit);
            ((IDictionary<string,object>)(this.ohlcvs != null && symbol != null && this.ohlcvs.ContainsKey(symbol) ? this.ohlcvs[symbol] : null))[timeframe] = stored;
        }
        ccxt.pro.ArrayCacheByTimestamp ohlcv = ((ccxt.pro.ArrayCacheByTimestamp)getValue((this.ohlcvs != null && symbol != null && this.ohlcvs.ContainsKey(symbol) ? this.ohlcvs[symbol] : null), timeframe));
        for (int i = 0; i < rows.Count; i++)
        {
            IList<object> parsed = this.parseOHLCV(rows[i], market);
            ohlcv.append(parsed);
        }
        string messageHash = ((("candles:" + timeframe) + ":") + symbol);
        client.resolve(ohlcv, messageHash);
    }

    /**
     * @method
     * @ignore
     * @name polymarket#authenticate
     * @description authenticates the websocket connection with the session proxy credentials, provisioning them first when needed
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} resolves once the connection is authenticated
     */
    public async virtual Task<object> authenticate(IDictionary<string, object>? parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        object credentials = await this.loadProxyCredentials();
        string? url = this.safeString((this.urls != null && this.urls.ContainsKey("api") ? this.urls["api"] : null), "ws");
        var client = this.client(url);
        string messageHash = "authenticated";
        var future = client.reusableFuture(messageHash);
        object authenticated = this.safeValue(client.subscriptions, messageHash);
        if ((authenticated == null))
        {
            Int64 id = this.requestId();
            Dictionary<string, object> pending = new Dictionary<string, object>() {
                { "method", "auth" },
                { "messageHashes", new List<object>() {messageHash} },
                { "subMessageHashes", new List<object>() {messageHash} },
            };
            ((IDictionary<string,object>)client.subscriptions)[(string)("req:" + id.ToString())] = pending;
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "id", id },
                { "req", "post" },
                { "op", new Dictionary<string, object>() {
                    { "type", "auth" },
                    { "args", new Dictionary<string, object>() {
                        { "proxy", this.safeString(credentials, "proxy") },
                        { "secret", this.safeString(credentials, "secret") },
                    } },
