    public virtual void handleOrder(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "ch": "orders",
        //         "ts": 1788546565800,
        //         "sq": 35879860000,
        //         "data": {
        //             "oid": 1234567890,
        //             "iid": 6,
        //             "buy": true,
        //             "p": "79000.0",
        //             "qty": "0.001",
        //             "tif": "gtc",
        //             "po": false,
        //             "ro": false,
        //             "rest": "0.001",
        //             "fill": "0",
        //             "cts": 1788546565789,
        //             "uts": 1788546565789,
        //             "status": "open"
        //         }
        //     }
        //
        object data = this.safeValue(message, "data");
        object rows = new List<object>() {};
        if (((data is IList<object>) || (data.GetType().IsGenericType && data.GetType().GetGenericTypeDefinition().IsAssignableFrom(typeof(List<>)))))
        {
            rows = data;
        } else
        {
            ((IList<object>)rows).Add(data);
        }
        int rowsLength = getArrayLength(rows);
        if ((rowsLength == 0))
        {
            return;
        }
        if ((this.orders == null))
        {
            Int64? limit = this.safeInteger(this.options, "ordersLimit", 1000);
            this.orders = new ArrayCacheBySymbolById(limit);
        }
        ccxt.pro.ArrayCache stored = this.orders;
        Dictionary<string, object> symbols = new Dictionary<string, object>() {};
        for (int i = 0; i < rowsLength; i++)
        {
            IDictionary<string, object> row = this.safeDict(rows, i, new Dictionary<string, object>() {});
            ccxt.Order parsed = this.parseOrder(row);
            stored.append(ccxt.BaseExchange.FromOrder(parsed));
            string? symbol = parsed.symbol;
            if ((symbol != null))
            {
                symbols[(string)symbol] = true;
            }
        }
        client.resolve(stored, "orders");
        List<object> symbolKeys = new List<object>(symbols.Keys);
        for (int i = 0; i < symbolKeys.Count; i++)
        {
            string? symbol = this.safeString(symbolKeys, i, "");
            client.resolve(stored, ("orders:" + symbol));
        }
    }

