        List<object> parts = ch.Split(new [] {"::"}, StringSplitOptions.None).ToList<object>();
        string? family = this.safeString(parts, 0, "");
        Dictionary<string, object> methods = new Dictionary<string, object>() {
            { "book", this.handleOrderBook },
            { "bbo", this.handleBidAsk },
            { "trades", this.handleTrades },
            { "tickers", this.handleTicker },
            { "klines", this.handleOHLCV },
            { "orders", this.handleOrder },
            { "fills", this.handleMyTrades },
            { "portfolio", this.handlePortfolio },
        };
        Delegate method = ((Delegate)this.safeValue(methods, family));
        if ((method != null))
        {
            DynamicInvoker.InvokeMethod(method, new object[] { client, message});
        }
    }

    public override object ping(WebSocketClient client)
